INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-11-09', 'Você não precisa ter todas as respostas para começar a transformar sua história.', 'Muitas vezes, esperamos ter certeza, segurança e condições perfeitas para dar um novo passo. Mas a clareza nem sempre aparece antes do movimento. Às vezes, é caminhando que descobrimos o que realmente queremos e do que somos capazes. O primeiro passo não precisa resolver tudo; ele só precisa abrir um caminho.', 'Escolha algo que você vem adiando e dê hoje um pequeno passo em direção a isso.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-11-10', 'Aquilo a que você dedica sua atenção ganha espaço dentro da sua vida.', 'Nossa atenção é uma forma de energia. Quando direcionamos constantemente o olhar para os problemas, as comparações e os medos, eles podem ocupar um espaço maior do que merecem. Isso não significa ignorar as dificuldades, mas aprender a escolher onde colocamos nossa presença.', 'Observe durante o dia quais pensamentos mais recebem sua atenção. Quando perceber um pensamento que não contribui, redirecione sua atenção para algo que possa construir.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-11-11', 'Quando você desperta para quem é, deixa de entregar ao mundo o poder de decidir quem deve ser.', 'PORTAL 11/11 — Simboliza despertar, alinhamento interior, consciência e intenção.
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-11-12', 'Você não precisa continuar sendo quem precisou ser para sobreviver.', 'Muitos comportamentos nasceram como formas de proteção. Talvez você tenha aprendido a agradar, controlar, esconder sentimentos ou evitar conflitos. Essas estratégias podem ter feito sentido em algum momento, mas não precisam determinar todas as suas escolhas futuras. Reconhecer sua história permite construir novas possibilidades.', 'Identifique um comportamento que você repete por proteção e pergunte-se: ainda preciso agir dessa maneira?', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-11-13', 'Dizer não ao que te distancia de si também é uma forma de dizer sim à sua vida.', 'Nem toda oportunidade precisa ser aceita, nem toda expectativa precisa ser atendida. Quando tentamos corresponder a tudo e a todos, podemos perder de vista nossas próprias necessidades. Os limites não são necessariamente muros contra o outro; muitas vezes, são caminhos de respeito por nós mesmas.', 'Escolha uma situação em que você precisa estabelecer um limite e pratique expressá-lo com clareza e respeito.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-11-14', 'Não diminua sua transformação só porque ela ainda não chegou ao resultado que você deseja.', 'Existe uma tendência de reconhecer apenas as grandes conquistas e ignorar os pequenos avanços. Mas cada escolha diferente, cada reação mais consciente e cada padrão interrompido também representam transformação. Nem todo crescimento é visível imediatamente. Algumas das mudanças mais importantes acontecem silenciosamente.', 'Reconheça três pequenas mudanças que você já conseguiu realizar, mesmo que ainda não tenha alcançado seu objetivo final.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-11-15', 'A liberdade começa quando você deixa de viver apenas pelas expectativas que colocaram sobre você.', 'PROCLAMAÇÃO DA REPÚBLICA — Uma reflexão sobre liberdade, autonomia e responsabilidade pelas próprias escolhas.
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-11-16', 'Às vezes, o que você procura no mundo é uma resposta que só poderá encontrar quando se permitir ouvir a si mesma.', 'Estamos acostumados a buscar opiniões, conselhos e confirmações externas. Embora ouvir outras pessoas possa ampliar nossa percepção, nenhuma delas consegue sentir exatamente o que acontece dentro de nós. Aprender a escutar as próprias emoções e necessidades é um caminho para desenvolver confiança interior.', 'Reserve dez minutos em silêncio e escreva o que você sente neste momento, sem tentar corrigir, justificar ou julgar suas emoções.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-11-17', 'A vida que você deseja também está sendo construída pelas escolhas que parecem pequenas hoje.', 'Nem sempre percebemos o impacto das decisões cotidianas. Uma conversa evitada, um hábito repetido, um compromisso assumido ou uma atitude de cuidado podem influenciar o caminho que estamos construindo. Grandes transformações não dependem apenas de grandes acontecimentos, mas também da maneira como escolhemos viver os dias comuns.', 'Escolha uma pequena atitude que esteja alinhada à vida que deseja construir e coloque-a em prática hoje.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-11-18', 'Você não precisa apagar o seu passado para permitir que o seu futuro seja diferente.', 'Nossa história é formada por experiências que nos ensinaram, marcaram e, algumas vezes, machucaram. Tentar negar o passado pode nos impedir de compreender como chegamos até aqui. Acolher a própria trajetória não significa concordar com tudo o que aconteceu, mas reconhecer que podemos aprender com ela sem permanecer presos ao que já passou.', 'Pense em uma experiência difícil que viveu e escreva uma coisa que ela ensinou sobre suas necessidades, seus limites ou sua força.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-11-19', 'Quando você transforma a caminhada do outro em medida para a sua, deixa de enxergar a beleza do próprio caminho.', 'Cada pessoa carrega uma história, um tempo e circunstâncias que não podem ser completamente comparados. Observar a conquista de alguém pode inspirar, mas também pode despertar a sensação de que estamos atrasados. O autoconhecimento nos ajuda a reconhecer que nosso valor não depende de estar no mesmo lugar que outra pessoa.', 'Perceba se está se comparando com alguém. Em seguida, escreva três avanços que fazem parte da sua própria trajetória.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-11-20', 'Reconhecer a humanidade do outro também transforma a maneira como enxergamos a nossa própria.', 'DIA NACIONAL DE ZUMBI E DA CONSCIÊNCIA NEGRA — Uma reflexão sobre ancestralidade, dignidade, igualdade, respeito e reconhecimento da história e da contribuição da população negra.
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-11-21', 'Recomeçar não é voltar ao início; é seguir adiante com a consciência que você conquistou.', 'Às vezes, interpretamos um recomeço como sinal de fracasso, como se todo o caminho percorrido tivesse sido perdido. Mas ninguém recomeça exatamente do mesmo lugar, porque as experiências vividas transformam nossa maneira de perceber e escolher. Recomeçar também pode ser uma demonstração de maturidade e respeito pelo que faz sentido agora.', 'Identifique algo que precisa de um novo começo e defina uma primeira atitude possível, sem exigir perfeição de si mesma.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-11-22', 'Estar presente é deixar de apenas atravessar a vida e começar a realmente experimentá-la.', 'Muitas vezes, o corpo está em um lugar enquanto a mente permanece presa ao passado ou antecipando o futuro. Com isso, momentos importantes passam despercebidos. A presença nos permite perceber detalhes, ouvir com atenção e experimentar a realidade com mais consciência. É no agora que nossas escolhas podem acontecer.', 'Escolha uma atividade cotidiana e faça-a com atenção plena. Observe os sons, os movimentos, as sensações e os detalhes que normalmente passam despercebidos.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-11-23', 'As crenças que você carrega sobre si podem se tornar limites que nunca foram realmente seus.', 'Muitas ideias que temos sobre nós mesmas foram construídas a partir de experiências, comentários e interpretações antigas. Com o tempo, algumas passam a parecer verdades absolutas. Questionar essas crenças não significa negar nossa história, mas permitir que nossa identidade continue evoluindo para além das conclusões que um dia fizemos sobre nós.', 'Escreva uma frase negativa que costuma repetir sobre si mesma. Depois, questione: quais fatos sustentam essa ideia e quais experiências mostram que ela não conta toda a minha história?', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-11-24', 'Você não precisa esconder o que sente para demonstrar que é forte.', 'Aprendemos, muitas vezes, que demonstrar emoções significa fraqueza. Por isso, tentamos controlar, disfarçar ou ignorar aquilo que sentimos. Mas reconhecer uma emoção é diferente de ser dominado por ela. Quando nos permitimos sentir com responsabilidade, abrimos espaço para compreender nossas necessidades e responder às situações com mais consciência.', 'Identifique a emoção que mais apareceu hoje. Dê um nome a ela e pergunte-se: o que essa emoção está tentando me mostrar?', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-11-25', 'Você também merece receber de si o cuidado que tantas vezes oferece ao mundo.', 'É comum dedicar tempo e energia às necessidades de outras pessoas enquanto adiamos nosso próprio cuidado. Aos poucos, podemos confundir disponibilidade constante com amor e responsabilidade. Cuidar de si não significa deixar de cuidar dos outros, mas reconhecer que suas necessidades também merecem atenção.', 'Faça hoje algo que represente cuidado consigo mesma: respeite um limite, descanse, alimente-se com atenção ou reserve um momento para algo que lhe faça bem.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-11-26', 'Nem tudo o que acontece merece uma reação imediata; algumas situações pedem apenas consciência.', 'Quando reagimos automaticamente, muitas vezes repetimos respostas construídas por experiências anteriores. Criar uma pausa entre o que acontece e a maneira como respondemos nos permite perceber nossas emoções e escolher uma atitude mais coerente com quem desejamos ser. Nem sempre podemos controlar o que acontece, mas podemos desenvolver consciência sobre nossas respostas.', 'Quando algo despertar irritação ou desconforto, faça uma pausa antes de responder. Respire, identifique o que sentiu e escolha conscientemente como agir.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-11-27', 'A maneira como você conversa consigo mesma também participa da maneira como experimenta a vida.', 'As palavras que dirigimos a nós mesmas podem fortalecer ou enfraquecer nossa percepção de valor. Muitas vezes, oferecemos compreensão às pessoas que amamos, mas tratamos nossos próprios erros com dureza. Desenvolver uma relação mais acolhedora consigo não significa deixar de reconhecer responsabilidades, mas aprender a crescer sem se maltratar.', 'Observe seu diálogo interno. Sempre que perceber uma crítica excessivamente dura, tente reformular a mensagem com a mesma honestidade, mas com mais respeito e compreensão.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-11-28', 'Nem todo movimento representa progresso; às vezes, avançar exige parar e perceber para onde você está indo.', 'A pressa pode nos fazer acreditar que precisamos estar sempre produzindo, resolvendo ou conquistando alguma coisa. Mas viver no automático também pode nos afastar das escolhas que realmente importam. Desacelerar permite observar o caminho, reconhecer o cansaço e perceber se nossas ações continuam alinhadas aos nossos valores.', 'Reserve quinze minutos sem telas ou tarefas. Pergunte-se se o ritmo que você está vivendo está respeitando suas necessidades atuais.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-11-29', 'Você não transforma aquilo que ainda não consegue reconhecer.', 'O primeiro movimento de uma transformação verdadeira é a disposição para olhar com honestidade para aquilo que acontece dentro de nós. Enquanto negamos sentimentos, justificamos comportamentos ou responsabilizamos apenas o mundo externo, perdemos oportunidades de compreender nossa participação nas próprias experiências. Reconhecer não é se culpar; é abrir espaço para uma escolha diferente.', 'Escolha uma situação recorrente em sua vida e observe qual é a sua participação nela. Procure identificar uma atitude que esteja ao seu alcance modificar.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-11-30', 'Alguns ciclos não precisam de mais uma tentativa; precisam da coragem de serem encerrados.', 'Existem situações que permanecem em nossa vida porque temos dificuldade de aceitar que já cumpriram seu papel. Insistir nem sempre significa perseverança; às vezes, significa medo de soltar aquilo que conhecemos. Encerrar um ciclo pode ser uma forma de reconhecer o que aprendemos e liberar espaço para novas experiências.', 'Pense em algo que você sente que precisa encerrar, modificar ou deixar de alimentar. Escreva qual atitude pode representar o início desse encerramento.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-01', 'Quando você escolhe conscientemente para onde deseja ir, cada pequeno passo começa a ganhar um novo significado.', 'Nem sempre temos controle sobre tudo o que acontece, mas podemos escolher a direção que desejamos seguir. Ter uma intenção não significa saber exatamente como chegar ao destino. Significa reconhecer o que é importante e permitir que essa consciência participe das suas escolhas.', 'Escreva uma intenção para este mês. Depois, escolha uma atitude simples que possa aproximar você dela.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-02', 'Um pensamento pode passar pela sua mente sem precisar se transformar em uma verdade sobre você.', 'Nossa mente produz interpretações o tempo todo. Algumas nascem de experiências antigas, medos e inseguranças. Quando acreditamos automaticamente em tudo o que pensamos, podemos limitar nossas próprias possibilidades. Observar um pensamento com distância é uma forma de recuperar a liberdade de escolher no que acreditar.', 'Quando surgir um pensamento negativo sobre você, pergunte: isso é um fato ou uma interpretação que estou fazendo?', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-03', 'Aceitar onde você está não significa desistir de descobrir até onde pode chegar.', 'Existe uma diferença entre reconhecer a realidade e se conformar com ela. O acolhimento permite olhar para o momento presente sem negar dificuldades ou exigir de si uma transformação imediata. É a partir desse reconhecimento que podemos identificar o que precisa mudar e encontrar caminhos possíveis.', 'Observe uma área da sua vida que gostaria de transformar. Escreva o que precisa aceitar no momento atual e o que já pode começar a mudar.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-04', 'Suas necessidades não deixam de existir só porque você aprendeu a colocar as dos outros em primeiro lugar.', 'Muitas vezes, nos acostumamos a atender expectativas, resolver problemas e cuidar de quem está ao nosso redor. Nesse movimento, podemos perder a percepção daquilo que também precisamos. Reconhecer suas necessidades não é egoísmo; é compreender que você também faz parte das relações que constrói.', 'Identifique uma necessidade sua que vem sendo deixada de lado e escolha uma maneira possível de atendê-la hoje.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-05', 'A busca pela perfeição pode fazer você deixar de viver a beleza do que já é possível.', 'Esperar o momento ideal, a condição perfeita ou a certeza absoluta pode se tornar uma maneira de adiar experiências importantes. Fazer algo com dedicação não significa precisar fazer tudo sem falhas. A vida também acontece nos ensaios, nas tentativas e nos caminhos que ainda estão sendo construídos.', 'Escolha algo que está adiando por querer fazer perfeitamente e permita-se começar com os recursos que tem.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-06', 'As relações que construímos também nos mostram partes de nós que talvez ainda não tenhamos aprendido a enxergar.', 'O convívio pode revelar nossas expectativas, inseguranças, limites e formas de buscar reconhecimento. Nem sempre aquilo que nos incomoda no outro fala exclusivamente sobre nós, mas nossas reações podem trazer informações importantes sobre nossas necessidades e experiências.', 'Pense em uma relação importante e observe: o que essa convivência tem ensinado sobre você?', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-07', 'Você não precisa diminuir sua essência para caber em lugares que exigem que deixe de ser você.', 'O desejo de pertencer pode nos levar a esconder opiniões, sentimentos e características para evitar rejeição. Mas pertencer não deveria exigir o abandono constante de si. Construir relações saudáveis também envolve encontrar espaços nos quais exista respeito pelas diferenças e liberdade para ser autêntico.', 'Observe em qual situação você costuma esconder uma parte de si para ser aceita. Pergunte-se o que precisaria mudar para se posicionar com mais autenticidade.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-08', 'Você não está atrasada por viver uma história que tem seu próprio ritmo.', 'Cada pessoa atravessa experiências, desafios e oportunidades diferentes. Comparar seu momento com o resultado alcançado por outra pessoa pode fazer você ignorar tudo o que já percorreu. Respeitar seu tempo não significa deixar de agir, mas reconhecer que seu caminho não precisa reproduzir o de ninguém.', 'Identifique uma cobrança que nasceu da comparação e transforme-a em uma meta que respeite sua realidade.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-09', 'Nem tudo o que acompanha você há muito tempo precisa continuar fazendo parte da sua história.', 'Há hábitos, crenças e formas de se relacionar que permanecem simplesmente porque se tornaram familiares. Mas familiaridade não é sinônimo de bem-estar. Quando começamos a perceber o que nos fortalece e o que nos limita, podemos escolher com mais consciência aquilo que desejamos levar adiante.', 'Escreva um hábito ou comportamento que deseja manter e outro que gostaria de transformar.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-10', 'Seu valor não depende da aprovação que recebe, mas do reconhecimento que desenvolve sobre si.', 'É natural desejar reconhecimento e acolhimento, mas quando nossa autoestima depende exclusivamente da opinião externa, entregamos aos outros o poder de definir como nos enxergamos. Desenvolver uma relação mais respeitosa consigo envolve reconhecer qualidades, limites, conquistas e possibilidades, mesmo quando ninguém está aplaudindo.', 'Escreva três características suas que você reconhece e valoriza, independentemente da opinião de outras pessoas.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-11', 'Olhar para dentro exige coragem, mas também pode revelar caminhos que você ainda não conseguiu enxergar.', 'O autoconhecimento nem sempre apresenta respostas confortáveis. Às vezes, ele nos aproxima de sentimentos evitados, padrões repetidos e escolhas que precisam ser revistas. Ainda assim, reconhecer o que acontece dentro de nós amplia nossa capacidade de agir de maneira diferente, em vez de apenas repetir o que já conhecemos.', 'Reserve alguns minutos para responder com sinceridade: o que tenho evitado reconhecer em mim?', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-12', 'A expansão acontece quando você deixa de rejeitar partes da sua história e começa a transformar o que aprendeu em consciência.', 'PORTAL 12/12 — simbolicamente associado à integração, ao encerramento de ciclos e à expansão da consciência.
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-13', 'Não espere chegar ao destino para reconhecer o valor de tudo o que já caminhou.', 'Quando estamos concentrados no que ainda falta, podemos deixar de perceber o quanto já avançamos. Algumas conquistas são visíveis; outras acontecem na maneira como reagimos, nos posicionamos e cuidamos de nós. Reconhecer o próprio progresso fortalece a confiança para continuar.', 'Liste cinco conquistas deste ano, incluindo aquelas que talvez ninguém tenha percebido além de você.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-14', 'Aquilo que você deseja começa a ganhar forma quando suas escolhas passam a caminhar na mesma direção.', 'Podemos desejar mudanças e, ao mesmo tempo, repetir atitudes que nos mantêm no mesmo lugar. Isso não significa falta de vontade, mas pode revelar hábitos, medos ou dificuldades que ainda precisam ser compreendidos. A transformação ganha consistência quando intenção e atitude começam a se aproximar.', 'Escolha um desejo importante e identifique uma atitude cotidiana que esteja alinhada com ele — ou que precise ser modificada.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-15', 'Você não precisa estar sempre oferecendo algo para merecer receber cuidado, carinho e atenção.', 'Algumas pessoas aprenderam a demonstrar amor principalmente fazendo, resolvendo e cuidando. Com o tempo, receber pode parecer desconfortável ou até gerar culpa. Permitir-se receber também faz parte de relações equilibradas. Você não precisa conquistar o direito de ser cuidada o tempo inteiro.', 'Quando alguém oferecer ajuda, carinho ou reconhecimento, experimente receber sem minimizar, recusar automaticamente ou sentir que precisa retribuir imediatamente.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-16', 'Reconhecer seus limites não diminui sua força; ajuda você a cuidar melhor dela.', 'Existe uma diferença entre superar desafios e ignorar constantemente os próprios sinais. Nem toda pausa é desistência, assim como nem toda insistência representa coragem. Conhecer seus limites permite distribuir melhor sua energia, respeitar suas necessidades e construir uma rotina mais sustentável.', 'Identifique um limite que precisa ser respeitado hoje e tome uma atitude concreta para não ultrapassá-lo.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-17', 'Sua energia é valiosa demais para ser entregue, sem consciência, a tudo o que exige sua atenção.', 'Nem toda preocupação precisa ocupar o mesmo espaço na sua vida. Algumas situações merecem ação; outras precisam de aceitação, distância ou simplesmente tempo. Quando aprendemos a distinguir o que está ao nosso alcance, deixamos de gastar tanta energia tentando controlar aquilo que não depende de nós.', 'Divida uma preocupação em duas partes: o que depende de você e o que não depende. Escolha uma ação possível para a primeira parte e permita-se soltar um pouco a segunda.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-18', 'Você tem o direito de mudar de ideia, de direção e de versão à medida que se conhece melhor.', 'Muitas vezes, permanecemos fiéis a escolhas antigas por medo de parecer incoerentes ou decepcionar alguém. Mas amadurecer também significa reconhecer quando algo deixou de fazer sentido. Você não precisa continuar defendendo uma versão de si apenas porque um dia acreditou que ela seria definitiva.', 'Pense em uma opinião, desejo ou escolha que mudou com o tempo. Reconheça o que essa mudança revela sobre seu crescimento.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-19', 'Enquanto você espera que tudo esteja resolvido, a vida continua acontecendo nos pequenos momentos de hoje.', 'É fácil condicionar a felicidade a um futuro em que tudo estará organizado, conquistado ou diferente. Mas a vida não começa depois que os problemas terminam. Encontrar momentos de presença e gratidão no cotidiano não significa ignorar o que precisa melhorar; significa não deixar que as preocupações ocupem todo o espaço.', 'Escolha um momento simples do seu dia e viva-o com atenção: uma refeição, uma conversa, um banho ou alguns minutos ao ar livre.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-20', 'Soltar não é negar o que foi importante; é reconhecer que nem tudo precisa permanecer.', 'Algumas experiências deixam marcas, vínculos e expectativas que continuam ocupando espaço mesmo depois de terem cumprido seu papel. Desapegar não exige apagar sentimentos nem desvalorizar o passado. Pode significar apenas parar de insistir em algo que já não acompanha quem você está se tornando.', 'Identifique algo que gostaria de começar a soltar. Escreva o que essa situação significou para você e o que deseja escolher daqui em diante.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-21', 'Assim como a natureza encontra novas formas de florescer, você também pode descobrir novas possibilidades em si.', 'INÍCIO DO VERÃO — às 17h50, no horário de Brasília. Simbolicamente, a estação representa vitalidade, expansão, movimento e florescimento.
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-22', 'O passado faz parte da sua história, mas não precisa continuar determinando todas as suas escolhas.', 'Experiências anteriores podem influenciar a maneira como confiamos, amamos, trabalhamos e enfrentamos desafios. Reconhecer essa influência é importante, mas não significa que precisamos repetir os mesmos caminhos. A consciência abre espaço para novas respostas diante de situações que antes pareciam inevitáveis.', 'Observe uma reação que costuma se repetir e pergunte: existe uma maneira diferente de responder a essa situação hoje?', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-23', 'Muitas vezes, o amor se revela menos nas grandes promessas e mais na presença que oferecemos todos os dias.', 'O cuidado pode aparecer em gestos simples: ouvir com atenção, respeitar um limite, demonstrar consideração ou estar disponível de verdade. Nas relações, pequenas atitudes consistentes podem construir segurança e proximidade. O amor também precisa encontrar espaço na rotina, e não apenas nas ocasiões especiais.', 'Demonstre carinho por alguém por meio de uma atitude simples e genuína, sem esperar uma ocasião especial.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-24', 'O presente mais significativo que você pode oferecer a alguém é estar verdadeiramente presente.', 'Em uma época marcada por encontros, expectativas e preparativos, podemos nos preocupar tanto em fazer tudo dar certo que esquecemos de viver o que está acontecendo. Cada família e cada pessoa atravessa esta data de uma maneira diferente. Não existe uma única forma de celebrar. O essencial pode estar em respeitar o momento, acolher as pessoas e valorizar os vínculos possíveis.', 'Em algum encontro ou conversa de hoje, deixe o celular de lado por alguns minutos e ofereça sua atenção inteira.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-25', 'O amor ganha força quando deixa de ser apenas sentimento e se transforma em presença, respeito e cuidado.', 'NATAL — data de significado religioso e cultural, associada por muitas pessoas ao nascimento de Jesus, ao amor, à esperança, à generosidade e à renovação.
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-26', 'Você não precisa transformar todos os sentimentos em explicações; alguns precisam primeiro ser acolhidos.', 'Nem sempre conseguimos compreender imediatamente o que sentimos. Às vezes, uma emoção surge misturada a lembranças, expectativas e acontecimentos recentes. Tentar encontrar uma resposta rápida pode aumentar a cobrança interna. Dar espaço ao sentimento, sem julgamento, pode ser o primeiro passo para entender o que ele está sinalizando.', 'Complete a frase: “Hoje, eu estou me sentindo... e talvez precise de...”. Escreva sem tentar corrigir ou justificar sua resposta.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-27', 'Às vezes, a maior transformação não está no que você conquistou, mas na maneira como passou a enxergar a vida.', 'Nem todo crescimento aparece em resultados materiais ou grandes acontecimentos. Ele também pode estar na capacidade de estabelecer limites, reconhecer emoções, escolher relações mais saudáveis ou lidar com situações de outra maneira. Perceber essas mudanças ajuda a dar significado ao caminho percorrido.', 'Lembre-se de como você reagia a uma situação no início do ano e compare com a maneira como reage hoje. O que mudou em você?', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-28', 'O fato de você ter repetido um caminho muitas vezes não significa que precise continuar caminhando por ele.', 'Padrões podem se tornar automáticos porque foram aprendidos ao longo de experiências e relações. Reconhecê-los não é motivo para se culpar, mas uma oportunidade de compreender o que os mantém. A mudança começa quando percebemos que, mesmo diante de situações conhecidas, podemos experimentar respostas novas.', 'Identifique um padrão que gostaria de transformar e escreva uma resposta diferente que poderia experimentar na próxima vez.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-29', 'Ser grata pelo que existe não impede você de desejar construir algo diferente.', 'A gratidão não precisa ser uma obrigação de estar feliz com tudo. É possível reconhecer o que foi importante e, ao mesmo tempo, admitir o que ainda dói, falta ou precisa mudar. Valorizar o presente e desejar um futuro diferente podem coexistir. Uma coisa não invalida a outra.', 'Escreva três coisas pelas quais sente gratidão e três coisas que deseja transformar no próximo ano.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-30', 'Você não precisa levar tudo o que viveu para o próximo capítulo da sua história.', 'A proximidade de um novo ano pode ser uma oportunidade simbólica de revisar o que merece continuar e o que pode ficar para trás. Algumas experiências deixam aprendizados; outras revelam limites e necessidades. Não é preciso resolver tudo de uma vez. O importante é escolher com mais consciência o que você deseja alimentar daqui em diante.', 'Faça duas listas: “O que desejo levar comigo” e “O que escolho deixar para trás”. Seja honesta sobre o que cada uma representa.', NULL, NOW()) ON CONFLICT (data) DO UPDATE SET frase = EXCLUDED.frase, reflexao = EXCLUDED.reflexao, convite = EXCLUDED.convite, atualizado_em = NOW();
INSERT INTO conteudo_dia (data, frase, reflexao, convite, imagem_url, atualizado_em) VALUES ('2026-12-31', 'Você não precisa terminar o ano com tudo resolvido; pode terminá-lo reconhecendo tudo o que aprendeu.', 'ENCERRAMENTO DE 2026 — momento simbólico de integração, gratidão, reconhecimento das experiências e liberação do que não precisa acompanhar o próximo ciclo.
